import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 4:
        return 'C'
    opp_last = history[-1][1]
    my_last = history[-1][0]
    opp_def = sum(1 for a, b in history if b == 'D')
    my_def = sum(1 for a, b in history if a == 'D')
    recent = history[-8:] if n >= 8 else history
    opp_recent_def = sum(1 for a, b in recent if b == 'D')
    if opp_recent_def >= len(recent) - 1 and len(recent) >= 4:
        return 'D'
    if n >= 40:
        score_gap = my_def - opp_def
        if opp_def > my_def + 2:
            return 'D'
        if my_def > opp_def + 4:
            return 'C'
    if n < 10:
        return 'C'
    if opp_last == 'D' and my_last == 'C':
        if rng.random() < 0.85:
            return 'D'
        else:
            return 'C'
    if opp_last == 'D' and my_last == 'D':
        if rng.random() < 0.7:
            return 'D'
        else:
            return 'C'
    pattern_defect = False
    if n >= 6:
        alt = sum(1 for i in range(n - 5, n - 1) if history[i][1] == 'D') >= 4
        if alt:
            pattern_defect = True
    if pattern_defect:
        return 'D'
    total = sum(1 for a, b in history if a == 'C' and b == 'C')
    if n >= 20:
        cc_rate = total / n
        if cc_rate > 0.8 and opp_def > 0:
            if rng.random() < 0.15:
                return 'D'
    if n >= 90:
        rem = 100 - n
        if rem <= 3:
            if opp_def > my_def:
                return 'D'
            else:
                return 'C'
    if opp_def == 0 and n >= 15:
        if rng.random() < 0.1:
            return 'D'
        return 'C'
    return 'C'
